1006	      LOG.error("Unable to get the container report for {} from SubCluster {}.",
1007	          applicationId, subClusterId.getId(), ex);
1008	    }
1009	
1010	    if (response == null) {
1011	      LOG.error("No response when attempting to retrieve the container " +
1012	          "report of the ContainerId = {} From SubCluster = {}.",
1013	          request.getContainerId(), subClusterId.getId());
1014	    }
1015	
1016	    long stopTime = clock.getTime();
1017	    routerMetrics.succeededGetContainerReportRetrieved(stopTime - startTime);
