55	  public static GetClusterMetricsResponse merge(
56	      Collection<GetClusterMetricsResponse> responses) {
57	    YarnClusterMetrics tmp = YarnClusterMetrics.newInstance(0);
58	    for (GetClusterMetricsResponse response : responses) {
59	      YarnClusterMetrics metrics = response.getClusterMetrics();
60	      tmp.setNumNodeManagers(
61	          tmp.getNumNodeManagers() + metrics.getNumNodeManagers());
62	      tmp.setNumActiveNodeManagers(
63	          tmp.getNumActiveNodeManagers() + metrics.getNumActiveNodeManagers());
64	      tmp.setNumDecommissionedNodeManagers(
65	          tmp.getNumDecommissionedNodeManagers() + metrics
66	              .getNumDecommissionedNodeManagers());
67	      tmp.setNumLostNodeManagers(
68	          tmp.getNumLostNodeManagers() + metrics.getNumLostNodeManagers());
69	      tmp.setNumRebootedNodeManagers(tmp.getNumRebootedNodeManagers() + metrics
70	          .getNumRebootedNodeManagers());
71	      tmp.setNumUnhealthyNodeManagers(
72	          tmp.getNumUnhealthyNodeManagers() + metrics
73	              .getNumUnhealthyNodeManagers());
74	    }
75	    return GetClusterMetricsResponse.newInstance(tmp);
76	  }
