78	  /**
79	   * Merges a list of ApplicationReports grouping by ApplicationId.
80	   * Our current policy is to merge the application reports from the reachable
81	   * SubClusters.
82	   * @param responses a list of ApplicationResponse to merge
83	   * @param returnPartialResult if the merge ApplicationReports should contain
84	   * partial result or not
85	   * @return the merged ApplicationsResponse
86	   */
87	  public static GetApplicationsResponse mergeApplications(
88	      Collection<GetApplicationsResponse> responses,
89	      boolean returnPartialResult){
90	    Map<ApplicationId, ApplicationReport> federationAM = new HashMap<>();
91	    Map<ApplicationId, ApplicationReport> federationUAMSum = new HashMap<>();
92	
93	    for (GetApplicationsResponse appResponse : responses){
94	      for (ApplicationReport appReport : appResponse.getApplicationList()){
95	        ApplicationId appId = appReport.getApplicationId();
96	        // Check if this ApplicationReport is an AM
97	        if (!appReport.isUnmanagedApp()) {
98	          // Insert in the list of AM
99	          federationAM.put(appId, appReport);
100	          // Check if there are any UAM found before
101	          if (federationUAMSum.containsKey(appId)) {
102	            // Merge the current AM with the found UAM
103	            mergeAMWithUAM(appReport, federationUAMSum.get(appId));
104	            // Remove the sum of the UAMs
105	            federationUAMSum.remove(appId);
106	          }
107	          // This ApplicationReport is an UAM
108	        } else if (federationAM.containsKey(appId)) {
109	          // Merge the current UAM with its own AM
110	          mergeAMWithUAM(federationAM.get(appId), appReport);
111	        } else if (federationUAMSum.containsKey(appId)) {
112	          // Merge the current UAM with its own UAM and update the list of UAM
113	          ApplicationReport mergedUAMReport =
114	              mergeUAMWithUAM(federationUAMSum.get(appId), appReport);
115	          federationUAMSum.put(appId, mergedUAMReport);
116	        } else {
117	          // Insert in the list of UAM
118	          federationUAMSum.put(appId, appReport);
119	        }
120	      }
121	    }
122	    // Check the remaining UAMs are depending or not from federation
123	    for (ApplicationReport appReport : federationUAMSum.values()) {
124	      if (mergeUamToReport(appReport.getName(), returnPartialResult)) {
125	        federationAM.put(appReport.getApplicationId(), appReport);
126	      }
127	    }
128	
129	    return GetApplicationsResponse.newInstance(federationAM.values());
130	  }
131	
132	  private static ApplicationReport mergeUAMWithUAM(ApplicationReport uam1,
133	      ApplicationReport uam2){
134	    uam1.setName(PARTIAL_REPORT + uam1.getApplicationId());
135	    mergeAMWithUAM(uam1, uam2);
136	    return uam1;
137	  }
138	
139	  private static void mergeAMWithUAM(ApplicationReport am,
140	      ApplicationReport uam){
141	    ApplicationResourceUsageReport amResourceReport =
142	        am.getApplicationResourceUsageReport();
143	
144	    ApplicationResourceUsageReport uamResourceReport =
145	        uam.getApplicationResourceUsageReport();
146	
147	    if (amResourceReport == null) {
148	      am.setApplicationResourceUsageReport(uamResourceReport);
149	    } else if (uamResourceReport != null) {
150	
151	      amResourceReport.setNumUsedContainers(
152	          amResourceReport.getNumUsedContainers() +
153	              uamResourceReport.getNumUsedContainers());
154	
155	      amResourceReport.setNumReservedContainers(
156	          amResourceReport.getNumReservedContainers() +
157	              uamResourceReport.getNumReservedContainers());
158	
159	      amResourceReport.setUsedResources(Resources.add(
160	          amResourceReport.getUsedResources(),
161	          uamResourceReport.getUsedResources()));
162	
163	      amResourceReport.setReservedResources(Resources.add(
164	          amResourceReport.getReservedResources(),
165	          uamResourceReport.getReservedResources()));
166	
167	      amResourceReport.setNeededResources(Resources.add(
168	          amResourceReport.getNeededResources(),
169	          uamResourceReport.getNeededResources()));
170	
171	      amResourceReport.setMemorySeconds(
172	          amResourceReport.getMemorySeconds() +
173	              uamResourceReport.getMemorySeconds());
174	
175	      amResourceReport.setVcoreSeconds(
176	          amResourceReport.getVcoreSeconds() +
177	              uamResourceReport.getVcoreSeconds());
178	
179	      amResourceReport.setQueueUsagePercentage(
180	          amResourceReport.getQueueUsagePercentage() +
181	              uamResourceReport.getQueueUsagePercentage());
182	
183	      amResourceReport.setClusterUsagePercentage(
184	          amResourceReport.getClusterUsagePercentage() +
185	              uamResourceReport.getClusterUsagePercentage());
186	
187	      am.setApplicationResourceUsageReport(amResourceReport);
188	    }
189	  }
