191	  /**
192	   * Returns whether or not to add an unmanaged application to the report.
193	   * @param appName Application Name
194	   * @param returnPartialResult if the merge ApplicationReports should contain
195	   * partial result or not
196	   */
197	  private static boolean mergeUamToReport(String appName,
198	      boolean returnPartialResult){
199	    if (returnPartialResult) {
200	      return true;
201	    }
202	    if (appName == null) {
203	      return false;
204	    }
205	    return !(appName.startsWith(UnmanagedApplicationManager.APP_NAME) ||
206	        appName.startsWith(PARTIAL_REPORT));
207	  }
